import java.util.Scanner;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Main {
    static int[] dr = {-1, 1, 0, 0};
    static int[] dc = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int L = sc.nextInt();
        int C = sc.nextInt();
        int P = sc.nextInt();

        boolean[][] black = new boolean[L][C];
        for (int i = 0; i < P; i++) {
            int x = sc.nextInt() - 1;
            int y = sc.nextInt() - 1;
            black[x][y] = true;
        }

        int[][] id = new int[L][C];
        for (int i = 0; i < L; i++) {
            Arrays.fill(id[i], -1);
        }

        List<int[]> candidates = new ArrayList<>();
        int N = 0;

        for (int r = 0; r < L; r++) {
            for (int c = 0; c < C; c++) {
                if (black[r][c]) continue;

                boolean adjacentToBlack = false;
                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];
                    if (nr >= 0 && nr < L && nc >= 0 && nc < C && black[nr][nc]) {
                        adjacentToBlack = true;
                        break;
                    }
                }

                if (adjacentToBlack) {
                    id[r][c] = N++;
                    candidates.add(new int[]{r, c});
                }
            }
        }

        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            adj.add(new ArrayList<>());
        }

        int[] parity = new int[N];
        for (int i = 0; i < N; i++) {
            int r = candidates.get(i)[0];
            int c = candidates.get(i)[1];
            parity[i] = (r + c) & 1;
        }

        for (int i = 0; i < N; i++) {
            int r = candidates.get(i)[0];
            int c = candidates.get(i)[1];

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < L && nc >= 0 && nc < C && id[nr][nc] != -1) {
                    adj.get(i).add(id[nr][nc]);
                }
            }
        }

        int[] match = new int[N];
        Arrays.fill(match, -1);
        boolean[] used = new boolean[N];

        int matching = 0;
        for (int i = 0; i < N; i++) {
            if (parity[i] == 0) {
                Arrays.fill(used, false);
                if (dfs(i, adj, parity, used, match)) {
                    matching++;
                }
            }
        }

        int answer = N - matching;
        System.out.println(answer);
    }

    static boolean dfs(int v, List<List<Integer>> adj, int[] parity, boolean[] used, int[] match) {
        for (int u : adj.get(v)) {
            if (parity[u] == 1 && !used[u]) {
                used[u] = true;
                if (match[u] == -1 || dfs(match[u], adj, parity, used, match)) {
                    match[u] = v;
                    return true;
                }
            }
        }
        return false;
    }
}
